import logging
from dataclasses import dataclass, field
from typing import Callable

from .db import DayState
from .metacritic import ListItem

log = logging.getLogger("selection")


@dataclass
class Selection:
    items: list[tuple[ListItem, str]] = field(default_factory=list)
    state: DayState | None = None
    pages_fetched: int = 0
    errors: list[tuple[str, Exception]] = field(default_factory=list)

    @property
    def sources(self) -> str:
        seen = []
        for _, src in self.items:
            if src not in seen:
                seen.append(src)
        return ", ".join(seen)


def select_batch(
    state: DayState,
    processed: set[int],
    fetch_new_releases: Callable[[], list[ListItem]],
    fetch_browse: Callable[[int, int], list[ListItem]],
    batch_size: int = 20,
    page_size: int = 24,
    max_pages: int = 4,
    retries: list[ListItem] | None = None,
) -> Selection:
    state = DayState(state.day, state.new_releases_done, state.browse_offset)
    sel = Selection(state=state)
    taken: set[int] = set()

    def take(items: list[ListItem], source: str) -> bool:
        for it in items:
            if it.id in processed or it.id in taken:
                continue
            if len(sel.items) >= batch_size:
                return False
            taken.add(it.id)
            sel.items.append((it, source))
        return True

    take(retries or [], "retry")

    if not state.new_releases_done:
        try:
            items = fetch_new_releases()
        except Exception as exc:
            log.warning("New Releases unavailable, falling back to SEE ALL for this run: %s", exc)
            sel.errors.append(("new-releases", exc))
        else:
            if take(items, "new-releases"):
                state.new_releases_done = True
            if any(src == "new-releases" for _, src in sel.items) or len(sel.items) >= batch_size:
                return sel

    while len(sel.items) < batch_size and sel.pages_fetched < max_pages:
        try:
            items = fetch_browse(state.browse_offset, page_size)
        except Exception as exc:
            if not sel.items:
                raise
            log.warning("SEE ALL page at offset %d unavailable: %s", state.browse_offset, exc)
            sel.errors.append((f"browse:{state.browse_offset}", exc))
            break
        sel.pages_fetched += 1
        if not items:
            break
        complete = take(items, f"browse:p{state.browse_offset // page_size + 1}")
        if not complete:
            break
        state.browse_offset += page_size
    return sel
import logging
import threading
from datetime import datetime, timedelta

from .config import Settings, iso, parse_iso, utcnow
from .db import Database
from .monitor import Monitor
from .pipeline import AlreadyRunning, Pipeline

log = logging.getLogger("scheduler")

OVERDUE_GRACE = timedelta(minutes=5)


def interval_of(settings: Settings) -> timedelta:
    return timedelta(minutes=max(1, settings.run_interval_minutes))


def last_run_start(db: Database) -> datetime | None:
    last = db.last_run()
    return parse_iso(last["started_at"]) if last else None


def initial_next_run(settings: Settings, db: Database, now: datetime | None = None) -> datetime:
    now = now or utcnow()
    soon = now + timedelta(seconds=settings.startup_delay_seconds)
    last_start = last_run_start(db)
    if last_start:
        return max(soon, last_start + interval_of(settings))
    if db.count_games() == 0:
        return soon
    return now + interval_of(settings)


class Scheduler:
    def __init__(self, settings: Settings, db: Database, pipeline: Pipeline, monitor: Monitor, clock=utcnow):
        self.settings = settings
        self.db = db
        self.pipeline = pipeline
        self.monitor = monitor
        self.clock = clock
        self._stop = threading.Event()
        self._thread: threading.Thread | None = None
        self.next_run: datetime | None = None
        self.last_tick_at: datetime | None = None
        self.last_error: str | None = None
        self.poll_seconds = 30.0
        self.min_wait_seconds = 1.0
        self._waiting_busy = False

    def start(self) -> None:
        if not self.settings.scheduler_enabled:
            self.monitor.set_worker("scheduler", "off", "планировщик выключен (SCHEDULER_ENABLED=0)")
            return
        self._stop.clear()
        self._thread = threading.Thread(target=self._loop, name="scheduler", daemon=True)
        self._thread.start()

    def stop(self) -> None:
        self._stop.set()
        if self._thread:
            self._thread.join(timeout=5)

    @property
    def alive(self) -> bool:
        return bool(self._thread and self._thread.is_alive())

    def _set_next(self, when: datetime) -> None:
        self.next_run = when
        self.monitor.set_next_run(when)
        local = when.astimezone(self.settings.day_tz).strftime("%H:%M:%S")
        self.monitor.set_worker("scheduler", "waiting", f"следующий запуск в {local}")

    def _refresh_next(self, now: datetime) -> None:
        if self.next_run is None:
            self._set_next(initial_next_run(self.settings, self.db, now))
            log.info("Scheduler started, next run at %s", iso(self.next_run))
            return
        last_start = last_run_start(self.db)
        if last_start and last_start + interval_of(self.settings) > self.next_run:
            self._set_next(last_start + interval_of(self.settings))

    def tick(self, now: datetime | None = None) -> str:
        now = now or self.clock()
        self.last_tick_at = now
        closed = self.db.close_stale_runs(now, self.settings.lease_ttl_seconds)
        if closed:
            log.warning("Closed %d run(s) left running by a stopped process", closed)
        self._refresh_next(now)
        if now < self.next_run:
            self._waiting_busy = False
            return "wait"
        if self.pipeline.running:
            if not self._waiting_busy:
                log.info("Scheduled run is due but another run is in progress, waiting for it to finish")
                self.monitor.set_worker("scheduler", "waiting", "плановый запуск ждёт окончания текущей обработки")
                self._waiting_busy = True
            return "busy"
        self._waiting_busy = False
        due = self.next_run
        self.next_run = now + interval_of(self.settings)
        self.monitor.set_next_run(self.next_run)
        self.monitor.set_worker("scheduler", "running", "плановый запуск обработки")
        outcome = "ran"
        try:
            self.pipeline.run("schedule")
        except AlreadyRunning:
            outcome = "busy"
        except Exception as exc:
            log.exception("Scheduled run crashed")
            self.last_error = f"{exc.__class__.__name__}: {exc}"
            outcome = "crashed"
        after = self.clock()
        last_start = last_run_start(self.db)
        if outcome == "busy":
            self._set_next(due)
        elif last_start:
            self._set_next(max(last_start + interval_of(self.settings), after + timedelta(seconds=1)))
        else:
            self._set_next(after + interval_of(self.settings))
        return outcome

    def _loop(self) -> None:
        while not self._stop.is_set():
            try:
                self.tick()
                self.last_error = None
                remaining = (self.next_run - self.clock()).total_seconds() if self.next_run else self.poll_seconds
            except Exception as exc:
                log.exception("Scheduler tick failed, retrying shortly")
                self.last_error = f"{exc.__class__.__name__}: {exc}"
                try:
                    self.monitor.set_worker("scheduler", "error", f"сбой планировщика: {exc}")
                except Exception:
                    pass
                remaining = self.poll_seconds
            self._stop.wait(min(max(remaining, self.min_wait_seconds), self.poll_seconds))
        self.monitor.set_worker("scheduler", "off", "остановлен")

    def health(self, now: datetime | None = None) -> dict:
        now = now or self.clock()
        info = {
            "enabled": self.settings.scheduler_enabled,
            "alive": self.alive,
            "next_run_at": iso(self.next_run),
            "last_tick_at": iso(self.last_tick_at),
            "last_error": self.last_error,
            "overdue_seconds": 0,
            "healthy": True,
        }
        if not self.settings.scheduler_enabled:
            return info
        if not self.alive:
            info["healthy"] = False
            return info
        if self.next_run and not self.pipeline.running:
            overdue = (now - self.next_run).total_seconds()
            info["overdue_seconds"] = max(0, round(overdue))
            if now - self.next_run > OVERDUE_GRACE:
                info["healthy"] = False
        return info

import html
import logging
import re
from dataclasses import dataclass, field
from typing import Any
from urllib.parse import urlparse

from .http_client import NotFound, PoliteClient, SchemaError

log = logging.getLogger("metacritic")

BACKEND = "https://backend.metacritic.com"
SITE = "https://www.metacritic.com"
IMG_PREFIX = f"{SITE}/a/img/catalog"

PLATFORM_SHORT = {
    "playstation-5": "PS5",
    "playstation-4": "PS4",
    "playstation-3": "PS3",
    "nintendo-switch-2": "NS2",
    "nintendo-switch": "NS",
    "xbox-series-x": "XSX",
    "xbox-one": "XONE",
    "xbox-360": "X360",
    "pc": "PC",
    "ios-iphoneipad": "iOS",
    "meta-quest": "Quest",
    "3ds": "3DS",
    "wii-u": "Wii U",
    "playstation-vita": "Vita",
}


def platform_short(slug: str | None, name: str | None) -> str:
    if slug and slug in PLATFORM_SHORT:
        return PLATFORM_SHORT[slug]
    return name or slug or "?"


def platform_slugify(name: str) -> str:
    return re.sub(r"[^a-z0-9]+", "-", name.lower()).strip("-")


VIDEO_HOSTS = frozenset({"cdn.jwplayer.com"})


def cover_url(bucket_path: str | None) -> str | None:
    if not isinstance(bucket_path, str) or not bucket_path.startswith("/") or bucket_path.startswith("//"):
        return None
    if any(ch in bucket_path for ch in "\"'<> \\"):
        return None
    return IMG_PREFIX + bucket_path


def safe_url(url: Any, hosts: frozenset[str] | None = None, schemes: tuple[str, ...] = ("https",)) -> str | None:
    if not isinstance(url, str):
        return None
    url = url.strip()
    try:
        parsed = urlparse(url)
    except ValueError:
        return None
    if parsed.scheme not in schemes or not parsed.hostname:
        return None
    if hosts is not None and parsed.hostname not in hosts:
        return None
    return url


