    var hintText = "Ручных запусков сегодня: " + manual.runs_today + (manual.daily_cap ? " из " + manual.daily_cap : "") +
      ". После каждого запуска пауза " + Math.round(manual.cooldown_seconds / 60) + " мин.";
    if (manual.code === "busy") {
